142	  private readonly handleMcpProgress = (payload: McpProgressPayload) => {
143	    const { callId } = payload;
144	
145	    const call = this.state.getToolCall(callId);
146	    if (!call || call.status !== CoreToolCallStatus.Executing) {
147	      return;
148	    }
149	
150	    const validTotal =
151	      payload.total !== undefined &&
152	      Number.isFinite(payload.total) &&
153	      payload.total > 0
154	        ? payload.total
155	        : undefined;
156	
157	    this.state.updateStatus(callId, CoreToolCallStatus.Executing, {
158	      progressMessage: payload.message,
159	      progressPercent: validTotal
160	        ? Math.min(100, (payload.progress / validTotal) * 100)
161	        : undefined,
162	      progress: payload.progress,
163	      progressTotal: validTotal,
164	    });
165	  };
