7	import type { Config } from '../config/config.js';
8	import { Scheduler } from '../scheduler/scheduler.js';
9	import type {
10	  ToolCallRequestInfo,
11	  CompletedToolCall,
12	} from '../scheduler/types.js';
13	import type { ToolRegistry } from '../tools/tool-registry.js';
