18	/**
19	 * Options for scheduling agent tools.
20	 */
21	export interface AgentSchedulingOptions {
22	  /** The unique ID for this agent's scheduler. */
23	  schedulerId: string;
24	  /** The name of the subagent. */
25	  subagent?: string;
26	  /** The ID of the tool call that invoked this agent. */
27	  parentCallId?: string;
28	  /** The tool registry specific to this agent. */
29	  toolRegistry: ToolRegistry;
30	  /** The prompt registry specific to this agent. */
31	  promptRegistry?: PromptRegistry;
32	  /** The resource registry specific to this agent. */
33	  resourceRegistry?: ResourceRegistry;
34	  /** AbortSignal for cancellation. */
35	  signal: AbortSignal;
36	  /** Optional function to get the preferred editor for tool modifications. */
37	  getPreferredEditor?: () => EditorType | undefined;
38	  /** Optional function to be notified when the scheduler is waiting for user confirmation. */
39	  onWaitingForConfirmation?: (waiting: boolean) => void;
40	}
41	
42	/**
43	 * Schedules a batch of tool calls for an agent using the new event-driven Scheduler.
44	 *
45	 * @param config The global runtime configuration.
46	 * @param requests The list of tool call requests from the agent.
47	 * @param options Scheduling options including registry and IDs.
48	 * @returns A promise that resolves to the completed tool calls.
49	 */
50	export async function scheduleAgentTools(
51	  config: Config,
52	  requests: ToolCallRequestInfo[],
53	  options: AgentSchedulingOptions,
54	): Promise<CompletedToolCall[]> {
55	  const {
56	    schedulerId,
57	    subagent,
58	    parentCallId,
59	    toolRegistry,
60	    promptRegistry,
61	    resourceRegistry,
62	    signal,
63	    getPreferredEditor,
64	    onWaitingForConfirmation,
65	  } = options;
66	
67	  const schedulerContext = {
68	    config,
69	    promptId: config.promptId,
70	    toolRegistry,
71	    promptRegistry: promptRegistry ?? config.getPromptRegistry(),
72	    resourceRegistry: resourceRegistry ?? config.getResourceRegistry(),
73	    messageBus: toolRegistry.messageBus,
74	    geminiClient: config.geminiClient,
75	    sandboxManager: config.sandboxManager,
76	  };
77	
78	  const scheduler = new Scheduler({
79	    context: schedulerContext,
80	    messageBus: toolRegistry.messageBus,
81	    getPreferredEditor: getPreferredEditor ?? (() => undefined),
82	    schedulerId,
83	    subagent,
84	    parentCallId,
85	    onWaitingForConfirmation,
86	  });
87	
88	  try {
89	    return await scheduler.schedule(requests, signal);
90	  } finally {
91	    scheduler.dispose();
92	  }
93	}
